<template>
  <div
    class="v2-ed"
    :class="{ 'v2-psd--drag': dragOver }"
    @pointerdown.stop @pointermove.stop @pointerup.stop
    @dragenter.prevent="onDragEnter"
    @dragover.prevent
    @dragleave="onDragLeave"
    @drop.prevent="onDrop"
  >
    <div class="v2-ed__canvas v2-psd__body">
      <div class="v2-psd__side">
        <div class="v2-psd__tree">
          <div v-if="!displayedRows.length" class="v2-ed__empty v2-psd__empty">
            {{ dragOver ? $t('psdLayerTree.dropHint') : $t('psdLayerTree.pickHint') }}
          </div>
          <button
            v-for="row in displayedRows"
            :key="row.id"
            type="button"
            class="v2-psd__row"
            :data-on="selectedSet.has(row.id) ? '1' : ''"
            :data-hidden="row.visible ? '' : '1'"
            :aria-selected="selectedSet.has(row.id)"
            :style="{ paddingLeft: `${8 + row.depth * 12 + (row.clip ? 12 : 0)}px` }"
            :title="rowTitle(row)"
            @click="selectRow(row.id, $event)"
          >
            <span class="v2-psd__chev" @click.stop="row.hasChildren && toggleCollapsed(row.id)">
              <i
                v-if="row.hasChildren"
                :class="['pi', collapsed.has(row.id) ? 'pi-chevron-right' : 'pi-chevron-down']"
              />
            </span>
            <i v-if="row.clip" class="pi pi-caret-up v2-psd__clip" />
            <span class="v2-psd__name">{{ row.name }}</span>
            <i v-if="row.warning" class="pi pi-exclamation-triangle v2-psd__warn" />
          </button>
        </div>
        <button
          type="button"
          class="v2-psd__expand"
          :data-on="dirty ? '1' : ''"
          :disabled="!displayedRows.length || exporting || loading"
          @click="exportAndExpand"
        >
          {{ exporting ? $t('psdLayerTree.exporting') : $t('psdLayerTree.export') }}
        </button>
      </div>
      <div class="v2-ed__fit v2-psd__preview">
        <ThumbImg
          v-if="previewUrl"
          class="v2-psd__img"
          :src="previewUrl"
          :thumb-max="THUMB_PREVIEW"
          draggable="false"
          @dragstart.prevent
        />
        <div v-else class="v2-ed__empty">{{ $t('psdLayerTree.pickHint') }}</div>
      </div>
    </div>

    <div class="v2-ed__panel">
      <div class="v2-ed__chips">
        <button type="button" class="v2-ed__chip" :disabled="loading" @click="pickLocalPsd()">
          {{ fileName || $t('psdLayerTree.pick') }}
        </button>
      </div>
    </div>

    <div class="v2-ed__status">
      <span
        v-if="outWidth && outHeight && (outWidth !== width || outHeight !== height)"
        class="v2-ed__dims"
      >{{ $t('psdLayerTree.scaled', { w: outWidth, h: outHeight, dw: width, dh: height }) }}</span>
      <span v-else-if="width && height" class="v2-ed__dims">{{ $t('psdLayerTree.dims', { w: width, h: height }) }}</span>
      <span class="v2-ed__spacer" />
      <span v-if="error">{{ error }}</span>
      <span v-else-if="loading" class="v2-ed__busy">{{ $t('psdLayerTree.loading') }}</span>
      <span v-else-if="exporting" class="v2-ed__busy">{{ $t('psdLayerTree.exporting') }}</span>
      <span v-else-if="compositing" class="v2-ed__busy">{{ $t('psdLayerTree.compositing') }}</span>
      <span v-else-if="dirty && previewUrl">{{ $t('psdLayerTree.dirtyHint') }}</span>
      <span v-else-if="!dirty && previewUrl" class="v2-ed__ok">{{ $t('psdLayerTree.done') }}</span>
      <span v-else-if="previewUrl">{{ $t('psdLayerTree.previewReady') }}</span>
      <span v-else-if="displayedRows.length">{{ $t('psdLayerTree.clickHint') }}</span>
      <span v-else>{{ $t('psdLayerTree.pickHint') }}</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'

import ThumbImg from '@/components/widgets/ThumbImg.vue'
import { spawnOrFocusImagesSplit } from '@/composables/stages/spawnFollowUp'
import { usePsdLayerTree } from '@/composables/stages/usePsdLayerTree'
import { t } from '@/i18n'
import type { LGraphNode } from '@/lib/comfyApp'
import type { StageState } from '@/stores/stageStore'
import { THUMB_PREVIEW } from '@/utils/thumbUrl'

const PSD_V2_H = 420

const props = defineProps<{
  node: LGraphNode
  state: StageState
}>()

const {
  fileName, width, height, outWidth, outHeight,
  displayedRows, selectedSet,
  loading, compositing, exporting, dirty, error, previewUrl,
  collapsed, toggleCollapsed, selectRow, pickFiles, pickLocalPsd, expandWithSlices,
} = usePsdLayerTree(props.node, props.state)

function rowTitle(row: { clip: boolean; warning: boolean }) {
  const parts: string[] = []
  if (row.clip) parts.push(t('psdLayerTree.clipping'))
  if (row.warning) parts.push(t('psdLayerTree.warning'))
  return parts.join(' — ') || undefined
}

function shrinkV2Window() {
  const node = props.node as any
  if (typeof node.setSize !== 'function') return
  const w = Number(node.size?.[0]) || 320
  const h = Number(node.size?.[1]) || 0
  if (h > PSD_V2_H) {
    node.setSize([w, PSD_V2_H])
    node.setDirtyCanvas?.(true, true)
  }
}

watch(displayedRows, (rows, prev) => {
  if (prev && rows.length < prev.length) shrinkV2Window()
})
shrinkV2Window()

const dragOver = ref(false)
let dragCount = 0

function onDragEnter() {
  dragCount++
  dragOver.value = true
}

function onDragLeave() {
  dragCount = Math.max(0, dragCount - 1)
  if (dragCount === 0) dragOver.value = false
}

function onDrop(e: DragEvent) {
  dragCount = 0
  dragOver.value = false
  pickFiles(Array.from(e.dataTransfer?.files ?? []))
}

async function exportAndExpand() {
  await expandWithSlices()
  spawnOrFocusImagesSplit(props.node)
}
</script>

